/// Raven `G_TestEntityPosition`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:86-111`
pub fn G_TestEntityPosition(ctx: GameContext<'_>, ent: *mut gentity_t) -> *mut gentity_t {
    unsafe {
        let mask = if (*ent).clipmask != 0 {
            (*ent).clipmask
        } else {
            CONTENTS_SOLID
        };

        let mut tr = core::mem::zeroed::<trace_t>();
        if !(*ent).client.is_null() {
            let client = (*ent).client as *mut crate::client::gclient::gclient_t;
            let mut v_max = (*ent).r.maxs;
            if v_max[2] < 1.0 {
                v_max[2] = 1.0;
            }
            trap::Trace(
                ctx.engine,
                GTraceArgs::new(
                    &mut tr as *mut trace_t,
                    &(*client).ps.origin as *const vec3_t,
                    &(*ent).r.mins as *const vec3_t,
                    &v_max as *const vec3_t,
                    &(*client).ps.origin as *const vec3_t,
                    (*ent).s.number,
                    mask,
                ),
            );
        } else {
            trap::Trace(
                ctx.engine,
                GTraceArgs::new(
                    &mut tr as *mut trace_t,
                    &(*ent).s.pos.trBase as *const vec3_t,
                    &(*ent).r.mins as *const vec3_t,
                    &(*ent).r.maxs as *const vec3_t,
                    &(*ent).s.pos.trBase as *const vec3_t,
                    (*ent).s.number,
                    mask,
                ),
            );
        }

        if tr.startsolid != 0 {
            &mut (*ctx.world).g_entities[tr.entityNum as usize] as *mut gentity_t
        } else {
            core::ptr::null_mut()
        }
    }
}

/// Raven `G_CreateRotationMatrix`.
///
/// `angles` is never written through in Raven (only read by `AngleVectors`),
/// so it stays by value; `matrix` is the `vec3_t matrix[3]` out-param, walked
/// as a 3-row array via pointer arithmetic (same convention as
/// `G_TransposeMatrix` in this file).
/// Source: `oracle/oracle/codemp/game/g_mover.c:118-121`
pub fn G_CreateRotationMatrix(angles: vec3_t, matrix: *mut vec3_t) {
    unsafe {
        AngleVectors(
            angles,
            Some(&mut *matrix.add(0)),
            Some(&mut *matrix.add(1)),
            Some(&mut *matrix.add(2)),
        );
        // Raven `VectorInverse(matrix[1])` — not itself ported anywhere in
        // the crate graph (call surface: unresolved), inlined here.
        for c in (*matrix.add(1)).iter_mut() {
            *c = -*c;
        }
    }
}

/// Raven `G_TransposeMatrix`.
///
/// `matrix`/`transpose` are Raven `vec3_t matrix[3]` — arrays of 3 rows that
/// decay to a `vec3_t *` at the call boundary, so the raw pointer here is
/// walked as a 3-row array via pointer arithmetic.
/// Source: `oracle/oracle/codemp/game/g_mover.c:128-135`
pub fn G_TransposeMatrix(matrix: *mut vec3_t, transpose: *mut vec3_t) {
    unsafe {
        for i in 0..3usize {
            for j in 0..3usize {
                (*transpose.add(i))[j] = (*matrix.add(j))[i];
            }
        }
    }
}

// Reshape: Raven's `point` is written through (`point[i] =
// DotProduct(...)`, read back by the caller), so it becomes `&mut vec3_t`
// per the ruling's non-nullable-out case. Same-file callers (below)
// updated to pass `&mut`.
/// Raven `G_RotatePoint`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:142-149`
pub fn G_RotatePoint(point: &mut vec3_t, matrix: *mut vec3_t) {
    unsafe {
        let tvec = *point;
        point[0] = (*matrix.add(0))[0] * tvec[0]
            + (*matrix.add(0))[1] * tvec[1]
            + (*matrix.add(0))[2] * tvec[2];
        point[1] = (*matrix.add(1))[0] * tvec[0]
            + (*matrix.add(1))[1] * tvec[1]
            + (*matrix.add(1))[2] * tvec[2];
        point[2] = (*matrix.add(2))[0] * tvec[0]
            + (*matrix.add(2))[1] * tvec[1]
            + (*matrix.add(2))[2] * tvec[2];
    }
}

/// Raven `G_TryPushingEntity`.
///
/// `move`/`amove` are read-only in Raven (never written back through), so
/// they stay by value ("keep by-value only if never written" clause).
/// Source: `oracle/oracle/codemp/game/g_mover.c:159-269`
pub fn G_TryPushingEntity(
    ctx: GameContext<'_>,
    check: *mut gentity_t,
    pusher: *mut gentity_t,
    r#move: vec3_t,
    amove: vec3_t,
) -> qboolean {
    unsafe {
        // This was only serverside not to mention it was never set (Raven
        // comment — the EF_MOVER_STOP branch is `#if 0`'d out, g_mover.c:164-172).
        if (*pusher).s.apos.trType != trType_t::TR_STATIONARY
            && ((*pusher).spawnflags & 16) != 0
            && crate::q_shared::Q_stricmp((*pusher).classname, c"func_rotating".as_ptr()) == 0
        {
            // just blow the fuck out of them
            G_Damage(
                ctx,
                check,
                pusher,
                pusher,
                None,
                [0.0, 0.0, 0.0],
                (*pusher).damage,
                0, // DAMAGE_NO_KNOCKBACK — not yet ported as a const; Raven passes it here.
                meansOfDeath_t::MOD_CRUSH as c_int,
            );
            return qtrue;
        }

        // save off the old position
        let world = &mut *ctx.world;
        let mut entry = PushedEntry {
            ent: check,
            origin: (*check).s.pos.trBase,
            angles: (*check).s.apos.trBase,
            deltayaw: 0,
        };
        if !(*check).client.is_null() {
            let client = (*check).client as *mut crate::client::gclient::gclient_t;
            entry.deltayaw = (*client).ps.delta_angles[YAW];
            entry.origin = (*client).ps.origin;
        }
        world.globals.pushed.push(entry);
        world.globals.pushed_p += 1;

        // try moving the contacted entity
        // figure movement due to the pusher's amove
        let mut transpose: [vec3_t; 3] = [[0.0; 3]; 3];
        let mut matrix: [vec3_t; 3] = [[0.0; 3]; 3];
        G_CreateRotationMatrix(amove, transpose.as_mut_ptr());
        G_TransposeMatrix(transpose.as_mut_ptr(), matrix.as_mut_ptr());

        let mut org = if !(*check).client.is_null() {
            let client = (*check).client as *mut crate::client::gclient::gclient_t;
            [
                (*client).ps.origin[0] - (*pusher).r.currentOrigin[0],
                (*client).ps.origin[1] - (*pusher).r.currentOrigin[1],
                (*client).ps.origin[2] - (*pusher).r.currentOrigin[2],
            ]
        } else {
            [
                (*check).s.pos.trBase[0] - (*pusher).r.currentOrigin[0],
                (*check).s.pos.trBase[1] - (*pusher).r.currentOrigin[1],
                (*check).s.pos.trBase[2] - (*pusher).r.currentOrigin[2],
            ]
        };
        let mut org2 = org;
        G_RotatePoint(&mut org2, matrix.as_mut_ptr());
        let move2 = [org2[0] - org[0], org2[1] - org[1], org2[2] - org[2]];

        // add movement
        for i in 0..3 {
            (*check).s.pos.trBase[i] += r#move[i];
            (*check).s.pos.trBase[i] += move2[i];
        }
        if !(*check).client.is_null() {
            let client = (*check).client as *mut crate::client::gclient::gclient_t;
            for i in 0..3 {
                (*client).ps.origin[i] += r#move[i];
                (*client).ps.origin[i] += move2[i];
            }
            // make sure the client's view rotates when on a rotating mover.
            // Raven `ANGLE2SHORT(x)` == `((int)((x)*65536/360) & 65535)`
            // (same transcription as `bg_pmove.rs:312`).
            (*client).ps.delta_angles[YAW] += ((amove[YAW] * 65536.0 / 360.0) as c_int) & 65535;
        }

        // may have pushed them off an edge
        if (*check).s.groundEntityNum != (*pusher).s.number {
            (*check).s.groundEntityNum = ENTITYNUM_NONE;
        }

        let mut block = G_TestEntityPosition(ctx, check);
        if block.is_null() {
            // pushed ok
            if !(*check).client.is_null() {
                let client = (*check).client as *mut crate::client::gclient::gclient_t;
                (*check).r.currentOrigin = (*client).ps.origin;
            } else {
                (*check).r.currentOrigin = (*check).s.pos.trBase;
            }
            trap::LinkEntity(ctx.engine, GLinkentityArgs::new(check));
            return qtrue;
        }

        if (*check).takedamage != 0
            && (*check).client.is_null()
            && (*check).s.weapon != 0
            && (*check).r.ownerNum < MAX_CLIENTS as c_int
            && (*check).health < 500
        {
            if (*check).health > 0 {
                G_Damage(
                    ctx,
                    check,
                    pusher,
                    pusher,
                    Some(&mut [0.0, 0.0, 0.0]), // Raven passes `vec3_origin` here.
                    (*check).r.currentOrigin,
                    999,
                    0,
                    meansOfDeath_t::MOD_UNKNOWN as c_int,
                );
            }
            return qfalse;
        }

        // if it is ok to leave in the old position, do it — this is only
        // relevant for riding entities, not pushed. Sliding trapdoors can
        // cause this.
        let last = world.globals.pushed[world.globals.pushed_p - 1];
        (*check).s.pos.trBase = last.origin;
        if !(*check).client.is_null() {
            let client = (*check).client as *mut crate::client::gclient::gclient_t;
            (*client).ps.origin = last.origin;
        }
        (*check).s.apos.trBase = last.angles;
        block = G_TestEntityPosition(ctx, check);
        if block.is_null() {
            (*check).s.groundEntityNum = -1;
            world.globals.pushed_p -= 1;
            world.globals.pushed.pop();
            return qtrue;
        }

        // blocked
        qfalse
    }
}

/// Raven `G_MoverPush`.
///
/// `move`/`amove` are read-only in Raven, so they stay by value.
/// Source: `oracle/oracle/codemp/game/g_mover.c:283-408`
pub fn G_MoverPush(
    ctx: GameContext<'_>,
    pusher: *mut gentity_t,
    r#move: vec3_t,
    amove: vec3_t,
    obstacle: *mut *mut gentity_t,
) -> qboolean {
    unsafe {
        *obstacle = core::ptr::null_mut();

        // mins/maxs are the bounds at the destination; totalMins/totalMaxs
        // are the bounds for the entire move.
        let (mut mins, mut maxs, mut total_mins, mut total_maxs) =
            ([0.0f32; 3], [0.0f32; 3], [0.0f32; 3], [0.0f32; 3]);
        if (*pusher).r.currentAngles[0] != 0.0
            || (*pusher).r.currentAngles[1] != 0.0
            || (*pusher).r.currentAngles[2] != 0.0
            || amove[0] != 0.0
            || amove[1] != 0.0
            || amove[2] != 0.0
        {
            let radius = RadiusFromBounds((*pusher).r.mins, (*pusher).r.maxs);
            for i in 0..3 {
                mins[i] = (*pusher).r.currentOrigin[i] + r#move[i] - radius;
                maxs[i] = (*pusher).r.currentOrigin[i] + r#move[i] + radius;
                total_mins[i] = mins[i] - r#move[i];
                total_maxs[i] = maxs[i] - r#move[i];
            }
        } else {
            for i in 0..3 {
                mins[i] = (*pusher).r.absmin[i] + r#move[i];
                maxs[i] = (*pusher).r.absmax[i] + r#move[i];
            }
            total_mins = (*pusher).r.absmin;
            total_maxs = (*pusher).r.absmax;
            for i in 0..3 {
                if r#move[i] > 0.0 {
                    total_maxs[i] += r#move[i];
                } else {
                    total_mins[i] += r#move[i];
                }
            }
        }

        // unlink the pusher so we don't get it in the entityList
        trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(pusher));

        let mut entity_list = [0i32; mp_qshared::shared::MAX_GENTITIES];
        let listed_entities = trap::EntitiesInBox(
            ctx.engine,
            GEntitiesInBoxArgs::new(
                &total_mins as *const vec3_t,
                &total_maxs as *const vec3_t,
                entity_list.as_mut_ptr(),
                entity_list.len() as c_int,
            ),
        );

        // move the pusher to its final position
        for i in 0..3 {
            (*pusher).r.currentOrigin[i] += r#move[i];
            (*pusher).r.currentAngles[i] += amove[i];
        }
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(pusher));

        // see if any solid entities are inside the final position
        for e in 0..listed_entities {
            let check =
                &mut (*ctx.world).g_entities[entity_list[e as usize] as usize] as *mut gentity_t;

            // only push items and players
            if (*check).s.eType != entityType_t::ET_PLAYER as c_int
                && (*check).s.eType != entityType_t::ET_NPC as c_int
                && (*check).physicsObject == 0
            {
                continue;
            }

            // if the entity is standing on the pusher, it will definitely be moved
            if (*check).s.groundEntityNum != (*pusher).s.number {
                // see if the ent needs to be tested
                if (*check).r.absmin[0] >= maxs[0]
                    || (*check).r.absmin[1] >= maxs[1]
                    || (*check).r.absmin[2] >= maxs[2]
                    || (*check).r.absmax[0] <= mins[0]
                    || (*check).r.absmax[1] <= mins[1]
                    || (*check).r.absmax[2] <= mins[2]
                {
                    continue;
                }
                // see if the ent's bbox is inside the pusher's final position —
                // this does allow a fast moving object to pass through a thin
                // entity...
                if G_TestEntityPosition(ctx, check).is_null() {
                    continue;
                }
            }

            // the entity needs to be pushed
            if G_TryPushingEntity(ctx, check, pusher, r#move, amove) != 0 {
                continue;
            }

            if (*pusher).damage != 0
                && !(*check).client.is_null()
                && ((*pusher).spawnflags & 32) != 0
            {
                G_Damage(
                    ctx,
                    check,
                    pusher,
                    pusher,
                    None,
                    [0.0, 0.0, 0.0],
                    (*pusher).damage,
                    0,
                    meansOfDeath_t::MOD_CRUSH as c_int,
                );
                continue;
            }

            if (*check).s.eType == entityType_t::ET_BODY as c_int
                || ((*check).s.eType == entityType_t::ET_PLAYER as c_int && (*check).health < 1)
            {
                // whatever, just crush it
                G_Damage(
                    ctx,
                    check,
                    pusher,
                    pusher,
                    None,
                    [0.0, 0.0, 0.0],
                    999,
                    0,
                    meansOfDeath_t::MOD_CRUSH as c_int,
                );
                continue;
            }

            // the move was blocked an entity

            // bobbing entities are instant-kill and never get blocked
            if (*pusher).s.pos.trType == trType_t::TR_SINE
                || (*pusher).s.apos.trType == trType_t::TR_SINE
            {
                G_Damage(
                    ctx,
                    check,
                    pusher,
                    pusher,
                    None,
                    [0.0, 0.0, 0.0],
                    99999,
                    0,
                    meansOfDeath_t::MOD_CRUSH as c_int,
                );
                continue;
            }

            // save off the obstacle so we can call the block function (crush, etc)
            *obstacle = check;

            // move back any entities we already moved — go backwards, so if
            // the same entity was pushed twice, it goes back to the
            // original position.
            // (Raven leaves `pushed_p` itself untouched here — only
            // `G_MoverTeam`'s next call resets it — so this walks the
            // snapshot without popping.)
            let world = &mut *ctx.world;
            for i in (0..world.globals.pushed_p).rev() {
                let p = world.globals.pushed[i];
                (*p.ent).s.pos.trBase = p.origin;
                (*p.ent).s.apos.trBase = p.angles;
                if !(*p.ent).client.is_null() {
                    let client = (*p.ent).client as *mut crate::client::gclient::gclient_t;
                    (*client).ps.delta_angles[YAW] = p.deltayaw;
                    (*client).ps.origin = p.origin;
                }
                trap::LinkEntity(ctx.engine, GLinkentityArgs::new(p.ent));
            }
            return qfalse;
        }

        qtrue
    }
}

// PORT-NOTE(bg-boundary): `BG_EvaluateTrajectory` (`bg_misc.rs`) is
// itself still parked (call surface: PARKED); called faithfully here and
// will panic until that lands.
/// Raven `G_MoverTeam`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:416-471`
pub fn G_MoverTeam(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let mut obstacle: *mut gentity_t = core::ptr::null_mut();

        // make sure all team slaves can move before commiting any moves or
        // calling any think functions — if the move is blocked, all moved
        // objects will be backed out.
        (*ctx.world).globals.pushed.clear();
        (*ctx.world).globals.pushed_p = 0;

        let mut part = ent;
        while !part.is_null() {
            let mut origin: vec3_t = [0.0; 3];
            let mut angles: vec3_t = [0.0; 3];
            let time = (*ctx.world).level.time;
            crate::bg_misc::BG_EvaluateTrajectory(
                &(*part).s.pos as *const trajectory_t,
                time,
                &mut origin,
            );
            crate::bg_misc::BG_EvaluateTrajectory(
                &(*part).s.apos as *const trajectory_t,
                time,
                &mut angles,
            );
            let r#move = [
                origin[0] - (*part).r.currentOrigin[0],
                origin[1] - (*part).r.currentOrigin[1],
                origin[2] - (*part).r.currentOrigin[2],
            ];
            let amove = [
                angles[0] - (*part).r.currentAngles[0],
                angles[1] - (*part).r.currentAngles[1],
                angles[2] - (*part).r.currentAngles[2],
            ];
            if r#move != [0.0, 0.0, 0.0] || amove != [0.0, 0.0, 0.0] {
                // actually moved
                if G_MoverPush(
                    ctx,
                    part,
                    r#move,
                    amove,
                    &mut obstacle as *mut *mut gentity_t,
                ) == 0
                {
                    break; // move was blocked
                }
            }
            part = crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*part).teamchain);
        }

        if !part.is_null() {
            // go back to the previous position
            let mut p = ent;
            while !p.is_null() {
                let dt = (*ctx.world).level.time - (*ctx.world).level.previousTime;
                (*p).s.pos.trTime += dt;
                (*p).s.apos.trTime += dt;
                let time = (*ctx.world).level.time;
                let mut cur_origin = (*p).r.currentOrigin;
                let mut cur_angles = (*p).r.currentAngles;
                crate::bg_misc::BG_EvaluateTrajectory(
                    &(*p).s.pos as *const trajectory_t,
                    time,
                    &mut cur_origin,
                );
                crate::bg_misc::BG_EvaluateTrajectory(
                    &(*p).s.apos as *const trajectory_t,
                    time,
                    &mut cur_angles,
                );
                (*p).r.currentOrigin = cur_origin;
                (*p).r.currentAngles = cur_angles;
                trap::LinkEntity(ctx.engine, GLinkentityArgs::new(p));
                p = crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*p).teamchain);
            }

            // if the pusher has a "blocked" function, call it
            if let Some(blocked) = (*ent).blocked.get() {
                crate::ent_fn_enums::dispatch_blocked(ctx, blocked, ent, obstacle);
            }
            return;
        }

        // the move succeeded
        let mut p = ent;
        while !p.is_null() {
            // call the reached function if time is at or past end point
            if (*p).s.pos.trType == trType_t::TR_LINEAR_STOP
                || (*p).s.pos.trType == trType_t::TR_NONLINEAR_STOP
            {
                if (*ctx.world).level.time >= (*p).s.pos.trTime + (*p).s.pos.trDuration {
                    if let Some(reached) = (*p).reached.get() {
                        crate::ent_fn_enums::dispatch_reached(ctx, reached, p);
                    }
                }
            }
            p = crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*p).teamchain);
        }
    }
}

/// Raven `G_RunMover`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:479-493`
pub fn G_RunMover(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        // if not a team captain, don't do anything, because the captain
        // will handle everything
        if (*ent).flags & crate::entity::flags::FL_TEAMSLAVE != 0 {
            return;
        }

        // if stationary at one of the positions, don't move anything
        if (*ent).s.pos.trType != trType_t::TR_STATIONARY
            || (*ent).s.apos.trType != trType_t::TR_STATIONARY
        {
            G_MoverTeam(ctx, ent);
        }

        // check think function
        crate::g_main::G_RunThink(ctx, ent);
    }
}

// Reshape: Raven's `center` is written through (built up across the
// slave loop, read back by every caller), so it becomes `&mut vec3_t` per
// the ruling's non-nullable-out case. Same-file callers updated below.
/// Raven `CalcTeamDoorCenter`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:511-528`
pub fn CalcTeamDoorCenter(ctx: GameContext<'_>, ent: *mut gentity_t, center: &mut vec3_t) {
    unsafe {
        // start with our own center
        for i in 0..3 {
            center[i] = ((*ent).r.mins[i] + (*ent).r.maxs[i]) * 0.5;
        }
        let mut slave = (*ent).teamchain;
        while let Some(slave_id) = slave {
            let slave_ptr = &mut (*ctx.world).g_entities[slave_id.index()] as *mut gentity_t;
            // find slave's center
            let mut slave_center = [0.0f32; 3];
            for i in 0..3 {
                slave_center[i] = ((*slave_ptr).r.mins[i] + (*slave_ptr).r.maxs[i]) * 0.5;
            }
            // add that to our own, find middle
            for i in 0..3 {
                center[i] = (center[i] + slave_center[i]) * 0.5;
            }
            slave = (*slave_ptr).teamchain;
        }
    }
}

/// Raven `SetMoverState`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:535-590`
pub fn SetMoverState(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    moverState: moverState_t,
    time: c_int,
) {
    unsafe {
        (*ent).moverState = moverState;
        (*ent).s.pos.trTime = time;

        if (*ent).s.pos.trDuration <= 0 {
            // don't allow divide by zero!
            (*ent).s.pos.trDuration = 1;
        }

        match moverState {
            MOVER_POS1 => {
                (*ent).s.pos.trBase = (*ent).pos1;
                (*ent).s.pos.trType = trType_t::TR_STATIONARY;
            }
            MOVER_POS2 => {
                (*ent).s.pos.trBase = (*ent).pos2;
                (*ent).s.pos.trType = trType_t::TR_STATIONARY;
            }
            MOVER_1TO2 => {
                (*ent).s.pos.trBase = (*ent).pos1;
                let delta = [
                    (*ent).pos2[0] - (*ent).pos1[0],
                    (*ent).pos2[1] - (*ent).pos1[1],
                    (*ent).pos2[2] - (*ent).pos1[2],
                ];
                let f = 1000.0 / (*ent).s.pos.trDuration as f32;
                (*ent).s.pos.trDelta = [delta[0] * f, delta[1] * f, delta[2] * f];
                (*ent).s.pos.trType = if (*ent).alt_fire != 0 {
                    trType_t::TR_LINEAR_STOP
                } else {
                    trType_t::TR_NONLINEAR_STOP
                };
            }
            MOVER_2TO1 => {
                (*ent).s.pos.trBase = (*ent).pos2;
                let delta = [
                    (*ent).pos1[0] - (*ent).pos2[0],
                    (*ent).pos1[1] - (*ent).pos2[1],
                    (*ent).pos1[2] - (*ent).pos2[2],
                ];
                let f = 1000.0 / (*ent).s.pos.trDuration as f32;
                (*ent).s.pos.trDelta = [delta[0] * f, delta[1] * f, delta[2] * f];
                (*ent).s.pos.trType = if (*ent).alt_fire != 0 {
                    trType_t::TR_LINEAR_STOP
                } else {
                    trType_t::TR_NONLINEAR_STOP
                };
            }
            _ => {}
        }
        let time = (*ctx.world).level.time;
        let mut cur_origin = (*ent).r.currentOrigin;
        crate::bg_misc::BG_EvaluateTrajectory(
            &(*ent).s.pos as *const trajectory_t,
            time,
            &mut cur_origin,
        );
        (*ent).r.currentOrigin = cur_origin;
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
    }
}

/// Raven `MatchTeam`.
///
/// All entities in a mover team move from pos1 to pos2 in the same amount
/// of time.
/// Source: `oracle/oracle/codemp/game/g_mover.c:600-606`
pub fn MatchTeam(ctx: GameContext<'_>, teamLeader: *mut gentity_t, moverState: c_int, time: c_int) {
    unsafe {
        let mut slave = teamLeader;
        while !slave.is_null() {
            SetMoverState(ctx, slave, moverState as moverState_t, time);
            slave =
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*slave).teamchain);
        }
    }
}

/// Raven `ReturnToPos1`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:615-625`
pub fn ReturnToPos1(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        (*ent).think = FnId::NONE;
        (*ent).nextthink = 0;
        (*ent).s.time = (*ctx.world).level.time;

        MatchTeam(ctx, ent, MOVER_2TO1, (*ctx.world).level.time);

        // starting sound
        G_PlayDoorLoopSound(ctx, ent);
        G_PlayDoorSound(ctx, ent, BMS_START); // ??
    }
}

/// Raven `Reached_BinaryMover`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:634-702`
pub fn Reached_BinaryMover(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        // stop the looping sound
        (*ent).s.loopSound = 0;
        (*ent).s.loopIsSoundset = qfalse;

        if (*ent).moverState == MOVER_1TO2 {
            // reached open
            let mut doorcenter: vec3_t = [0.0; 3];

            SetMoverState(ctx, ent, MOVER_POS2, (*ctx.world).level.time);
            CalcTeamDoorCenter(ctx, ent, &mut doorcenter);
            G_PlayDoorSound(ctx, ent, BMS_END);

            if (*ent).wait < 0.0 {
                // done for good
                (*ent).think = FnId::NONE;
                (*ent).nextthink = 0;
                (*ent).use_ = FnId::NONE;
            } else {
                // return to pos1 after a delay
                (*ent).think = Some(EntThink::ReturnToPos1).into();
                if (*ent).spawnflags & 8 != 0 {
                    // toggle, keep think, wait for next use
                    (*ent).nextthink = -1;
                } else {
                    (*ent).nextthink = (*ctx.world).level.time + (*ent).wait as c_int;
                }
            }

            // fire targets
            if (*ent).activator.is_none() {
                (*ent).activator = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), ent);
            }
            G_UseTargets2(
                ctx,
                ent,
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).activator),
                (*ent).opentarget,
            );
        } else if (*ent).moverState == MOVER_2TO1 {
            // closed
            let mut doorcenter: vec3_t = [0.0; 3];

            SetMoverState(ctx, ent, MOVER_POS1, (*ctx.world).level.time);
            CalcTeamDoorCenter(ctx, ent, &mut doorcenter);
            G_PlayDoorSound(ctx, ent, BMS_END);

            // close areaportals
            if crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).teammaster)
                == ent
                || (*ent).teammaster.is_none()
            {
                trap::AdjustAreaPortalState(
                    ctx.engine,
                    GAdjustAreaPortalStateArgs::new(ent, qfalse),
                );
            }
            G_UseTargets2(
                ctx,
                ent,
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).activator),
                (*ent).closetarget,
            );
        } else {
            G_Error(ctx, c"Reached_BinaryMover: bad moverState".as_ptr());
        }
    }
}

/// Raven `Use_BinaryMover_Go`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:710-828`
pub fn Use_BinaryMover_Go(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let activator = (*ent).activator;
        (*ent).activator = activator;

        if (*ent).moverState == MOVER_POS1 {
            let mut doorcenter: vec3_t = [0.0; 3];

            // start moving 50 msec later, because if this was player
            // triggered, level.time hasn't been advanced yet
            MatchTeam(ctx, ent, MOVER_1TO2, (*ctx.world).level.time + 50);
            CalcTeamDoorCenter(ctx, ent, &mut doorcenter);

            // starting sound
            G_PlayDoorLoopSound(ctx, ent);
            G_PlayDoorSound(ctx, ent, BMS_START);
            (*ent).s.time = (*ctx.world).level.time;

            // open areaportal
            if crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).teammaster)
                == ent
                || (*ent).teammaster.is_none()
            {
                trap::AdjustAreaPortalState(
                    ctx.engine,
                    GAdjustAreaPortalStateArgs::new(ent, qtrue),
                );
            }
            G_UseTargets(
                ctx,
                ent,
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).activator),
            );
            return;
        }

        // if all the way up, just delay before coming down
        if (*ent).moverState == MOVER_POS2 {
            // have to do this because the delay sets our think to Use_BinaryMover_Go
            (*ent).think = Some(EntThink::ReturnToPos1).into();
            if (*ent).spawnflags & 8 != 0 {
                // TOGGLE doors don't use wait!
                (*ent).nextthink = (*ctx.world).level.time + FRAMETIME;
            } else {
                (*ent).nextthink = (*ctx.world).level.time + (*ent).wait as c_int;
            }
            G_UseTargets2(
                ctx,
                ent,
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).activator),
                (*ent).target2,
            );
            return;
        }

        // only partway down before reversing
        if (*ent).moverState == MOVER_2TO1 {
            let total;
            let partial;
            if (*ent).s.pos.trType == trType_t::TR_NONLINEAR_STOP {
                let cur_total = (*ent).s.pos.trDuration - 50;
                let cur_delta = [
                    (*ent).r.currentOrigin[0] - (*ent).pos1[0],
                    (*ent).r.currentOrigin[1] - (*ent).pos1[1],
                    (*ent).r.currentOrigin[2] - (*ent).pos1[2],
                ];
                // Raven runs fPartial through double libm: VectorLength narrows a double
                // sqrt to float, acos is the double call, and RAD2DEG is `(a*180.0f)/M_PI`
                // with double M_PI. fPartial narrows back to float after each assignment.
                let mut f_partial = VectorLength(cur_delta) / VectorLength((*ent).s.pos.trDelta);
                f_partial /= (*ent).s.pos.trDuration as f32;
                f_partial /= 0.001f32;
                f_partial = (f_partial as f64).acos() as f32;
                f_partial = ((f_partial * 180.0f32) as f64 / core::f64::consts::PI) as f32;
                f_partial = (90.0 - f_partial) / 90.0 * (*ent).s.pos.trDuration as f32;
                total = cur_total;
                partial = total - f_partial.floor() as c_int;
            } else {
                total = (*ent).s.pos.trDuration;
                partial = (*ctx.world).level.time - (*ent).s.pos.trTime;
            }

            let partial = if partial > total { total } else { partial };
            (*ent).s.pos.trTime = (*ctx.world).level.time - (total - partial);

            MatchTeam(ctx, ent, MOVER_1TO2, (*ent).s.pos.trTime);
            G_PlayDoorSound(ctx, ent, BMS_START);
            return;
        }

        // only partway up before reversing
        if (*ent).moverState == MOVER_1TO2 {
            let total;
            let partial;
            if (*ent).s.pos.trType == trType_t::TR_NONLINEAR_STOP {
                let cur_total = (*ent).s.pos.trDuration - 50;
                let cur_delta = [
                    (*ent).r.currentOrigin[0] - (*ent).pos2[0],
                    (*ent).r.currentOrigin[1] - (*ent).pos2[1],
                    (*ent).r.currentOrigin[2] - (*ent).pos2[2],
                ];
                // Raven runs fPartial through double libm: VectorLength narrows a double
                // sqrt to float, acos is the double call, and RAD2DEG is `(a*180.0f)/M_PI`
                // with double M_PI. fPartial narrows back to float after each assignment.
                let mut f_partial = VectorLength(cur_delta) / VectorLength((*ent).s.pos.trDelta);
                f_partial /= (*ent).s.pos.trDuration as f32;
                f_partial /= 0.001f32;
                f_partial = (f_partial as f64).acos() as f32;
                f_partial = ((f_partial * 180.0f32) as f64 / core::f64::consts::PI) as f32;
                f_partial = (90.0 - f_partial) / 90.0 * (*ent).s.pos.trDuration as f32;
                total = cur_total;
                partial = total - f_partial.floor() as c_int;
            } else {
                total = (*ent).s.pos.trDuration;
                partial = (*ctx.world).level.time - (*ent).s.pos.trTime;
            }

            let partial = if partial > total { total } else { partial };
            (*ent).s.pos.trTime = (*ctx.world).level.time - (total - partial);

            MatchTeam(ctx, ent, MOVER_2TO1, (*ent).s.pos.trTime);
            G_PlayDoorSound(ctx, ent, BMS_START);
        }
    }
}

/// Raven `UnLockDoors`.
///
/// Go through and unlock the door and all the slaves.
/// `ent` is declared `gentity_t *const` in Raven (a const *pointer*, not a
/// const pointee) — the fields are still mutated, so the cast to `*mut` here
/// just recovers writability, not a behavior change.
/// Source: `oracle/oracle/codemp/game/g_mover.c:830-845`
pub fn UnLockDoors(ent: *const gentity_t) {
    unsafe {
        let mut slave = ent as *mut gentity_t;
        loop {
            // want to allow locked toggle doors, so keep the targetname
            if (*slave).spawnflags & MOVER_TOGGLE == 0 {
                (*slave).targetname = core::ptr::null_mut(); // not usable ever again
            }
            (*slave).spawnflags &= !MOVER_LOCKED;
            (*slave).s.frame = 1; // second stage of anim
            slave = crate::ent_id::resolve(
                slave.offset(-((*slave).s.number as isize)),
                (*slave).teamchain,
            );
            if slave.is_null() {
                break;
            }
        }
    }
}

/// Raven `LockDoors`.
///
/// Go through and lock the door and all the slaves.
/// Source: `oracle/oracle/codemp/game/g_mover.c:846-857`
pub fn LockDoors(ent: *const gentity_t) {
    unsafe {
        let mut slave = ent as *mut gentity_t;
        loop {
            (*slave).spawnflags |= MOVER_LOCKED;
            (*slave).s.frame = 0; // first stage of anim
            slave = crate::ent_id::resolve(
                slave.offset(-((*slave).s.number as isize)),
                (*slave).teamchain,
            );
            if slave.is_null() {
                break;
            }
        }
    }
}

/// Raven `Use_BinaryMover`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:863-901`
pub fn Use_BinaryMover(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        if (*ent).use_.is_none() {
            // I cannot be used anymore, must be a door with a wait of -1 that's opened.
            return;
        }

        // only the master should be used
        if (*ent).flags & crate::entity::flags::FL_TEAMSLAVE != 0 {
            Use_BinaryMover(
                ctx,
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).teammaster),
                other,
                activator,
            );
            return;
        }

        if (*ent).flags & crate::entity::flags::FL_INACTIVE != 0 {
            return;
        }

        if (*ent).spawnflags & MOVER_LOCKED != 0 {
            // a locked door, unlock it
            UnLockDoors(ent);
            return;
        }

        G_ActivateBehavior(ctx, ent, bSet_t::BSET_USE as c_int);

        (*ent).enemy = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), other);
        (*ent).activator = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), activator);
        if (*ent).delay != 0 {
            (*ent).think = Some(EntThink::Use_BinaryMover_Go).into();
            (*ent).nextthink = (*ctx.world).level.time + (*ent).delay;
        } else {
            Use_BinaryMover_Go(ctx, ent);
        }
    }
}

/// Raven `InitMoverTrData`.
///
/// "pos1", "pos2", and "speed" should be set before calling, so the
/// movement delta can be calculated.
/// Source: `oracle/oracle/codemp/game/g_mover.c:913-934`
pub fn InitMoverTrData(ent: *mut gentity_t) {
    unsafe {
        (*ent).s.pos.trType = trType_t::TR_STATIONARY;
        (*ent).s.pos.trBase = (*ent).pos1;

        // calculate time to reach second position from speed
        let pos1 = (*ent).pos1;
        let pos2 = (*ent).pos2;
        let r#move = [pos2[0] - pos1[0], pos2[1] - pos1[1], pos2[2] - pos1[2]];
        // Raven uses VectorLength, whose sqrt is the double libm call narrowed to float;
        // an inline f32 sqrt double-rounds and diverges from the oracle.
        let distance = VectorLength(r#move);
        if (*ent).speed == 0.0 {
            (*ent).speed = 100.0;
        }
        let speed = (*ent).speed;
        (*ent).s.pos.trDelta = [r#move[0] * speed, r#move[1] * speed, r#move[2] * speed];
        (*ent).s.pos.trDuration = (distance * 1000.0 / speed) as c_int;
        if (*ent).s.pos.trDuration <= 0 {
            (*ent).s.pos.trDuration = 1;
        }
    }
}

/// Raven `InitMover`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:936-999`
pub fn InitMover(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        // if the "model2" key is set, use a seperate model
        // for drawing, but clip against the brushes
        if !(*ent).model2.is_null() && *(*ent).model2 != 0 {
            // Raven `strstr(ent->model2, ".glm")` — use Rust string contains check
            if std::ffi::CStr::from_ptr((*ent).model2)
                .to_string_lossy()
                .contains(".glm")
            {
                // for now, not supported in MP.
                (*ent).s.modelindex2 = 0;
            } else {
                (*ent).s.modelindex2 = G_ModelIndex((*ent).model2);
            }
        }

        // if the "color" or "light" keys are set, setup constantLight
        let mut light = 0.0f32;
        let mut color: vec3_t = [0.0; 3];
        let light_set = G_SpawnFloat(
            ctx,
            c"light".as_ptr(),
            c"100".as_ptr(),
            &mut light as *mut f32,
        );
        let color_set = G_SpawnVector(
            ctx,
            c"color".as_ptr(),
            c"1 1 1".as_ptr(),
            color.as_mut_ptr(),
        );
        if light_set != 0 || color_set != 0 {
            let mut r = (color[0] * 255.0) as c_int;
            if r > 255 {
                r = 255;
            }
            let mut g = (color[1] * 255.0) as c_int;
            if g > 255 {
                g = 255;
            }
            let mut b = (color[2] * 255.0) as c_int;
            if b > 255 {
                b = 255;
            }
            let mut i = (light / 4.0) as c_int;
            if i > 255 {
                i = 255;
            }
            (*ent).s.constantLight = r | (g << 8) | (b << 16) | (i << 24);
        }

        (*ent).use_ = Some(EntUse::Use_BinaryMover).into();
        (*ent).reached = Some(EntReached::Reached_BinaryMover).into();

        (*ent).moverState = MOVER_POS1;
        (*ent).r.svFlags = SVF_USE_CURRENT_ORIGIN;
        if (*ent).spawnflags & MOVER_INACTIVE != 0 {
            // Make it inactive
            (*ent).flags |= crate::entity::flags::FL_INACTIVE;
        }
        if (*ent).spawnflags & MOVER_PLAYER_USE != 0 {
            // Can be used by the player's BUTTON_USE
            (*ent).r.svFlags |= SVF_PLAYER_USABLE;
        }
        (*ent).s.eType = entityType_t::ET_MOVER as c_int;
        crate::q_math::_VectorCopy((*ent).pos1, &mut (*ent).r.currentOrigin);
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));

        InitMoverTrData(ent);
    }
}

/// Raven `Blocked_Door`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1018-1029`
pub fn Blocked_Door(ctx: GameContext<'_>, ent: *mut gentity_t, other: *mut gentity_t) {
    unsafe {
        if (*ent).damage != 0 {
            // Resolved `G_Damage` takes `dir`/`point` by value (Raven passes
            // NULL pointers here); substitute the zero vector since `G_Damage`
            // is itself an unported stub either way.
            G_Damage(
                ctx,
                other,
                ent,
                ent,
                None,
                [0.0, 0.0, 0.0],
                (*ent).damage,
                0,
                meansOfDeath_t::MOD_CRUSH as c_int,
            );
        }
        if (*ent).spawnflags & MOVER_CRUSHER != 0 {
            return; // crushers don't reverse
        }

        // reverse direction
        Use_BinaryMover(ctx, ent, ent, other);
    }
}

/// Raven `Touch_DoorTriggerSpectator`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1037-1071`
pub fn Touch_DoorTriggerSpectator(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    _trace: *mut trace_t,
) {
    unsafe {
        // `DEFAULT_MINS_2`/`DEFAULT_MAXS_2` canonical in
        // `mp_bg::public::viewheight` (`c_int`, cast here to match the
        // `vec3_t` components they seed).
        // Source: `oracle/oracle/codemp/game/bg_public.h:41-42`
        const DEFAULT_MINS_2: f32 = mp_bg::public::viewheight::DEFAULT_MINS_2 as f32;
        const DEFAULT_MAXS_2: f32 = mp_bg::public::viewheight::DEFAULT_MAXS_2 as f32;

        let axis = (*ent).count as usize;
        let mut dir: vec3_t = [0.0; 3];
        let mut origin: vec3_t = [0.0; 3];

        if ((*other).s.origin[axis] - (*ent).r.absmax[axis]).abs()
            < ((*other).s.origin[axis] - (*ent).r.absmin[axis]).abs()
        {
            origin[axis] = (*ent).r.absmin[axis] - 10.0;
            dir[axis] = -1.0;
        } else {
            origin[axis] = (*ent).r.absmax[axis] + 10.0;
            dir[axis] = 1.0;
        }

        for i in 0..3 {
            if i == axis {
                continue;
            }
            origin[i] = ((*ent).r.absmin[i] + (*ent).r.absmax[i]) * 0.5;
        }

        let mut angles: vec3_t = [0.0; 3];
        crate::q_math::vectoangles(dir, &mut angles);

        let p_mins = [-15.0f32, -15.0, DEFAULT_MINS_2];
        let p_maxs = [15.0f32, 15.0, DEFAULT_MAXS_2];

        let mut tr = core::mem::zeroed::<trace_t>();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(
                &mut tr as *mut trace_t,
                &origin as *const vec3_t,
                &p_mins as *const vec3_t,
                &p_maxs as *const vec3_t,
                &origin as *const vec3_t,
                (*other).s.number,
                (*other).clipmask,
            ),
        );

        if tr.startsolid == 0
            && tr.allsolid == 0
            && tr.fraction == 1.0f32
            && tr.entityNum as c_int == ENTITYNUM_NONE
        {
            TeleportPlayer(ctx, other, origin, angles);
        }
    }
}

/// Raven `Touch_DoorTrigger`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1078-1158`
pub fn Touch_DoorTrigger(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    trace: *mut trace_t,
) {
    unsafe {
        let mut relock_ent: *mut gentity_t = core::ptr::null_mut();
        let parent = match (*ent).parent {
            Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
            None => core::ptr::null_mut(),
        };

        if !(*other).client.is_null()
            && (*((*other).client as *mut gclient_t)).sess.sessionTeam == TEAM_SPECTATOR
        {
            // if the door is not open and not opening
            if (*parent).moverState != MOVER_1TO2 && (*parent).moverState != MOVER_POS2 {
                Touch_DoorTriggerSpectator(ctx, ent, other, trace);
            }
            return;
        }

        if (*ent).genericValue14 == 0 && ((*ent).parent.is_none() || (*parent).genericValue14 == 0)
        {
            if !(*other).client.is_null()
                && (*other).s.number >= MAX_CLIENTS as c_int
                && (*other).s.eType == entityType_t::ET_NPC as c_int
                && (*other).s.NPC_class == class_t::CLASS_VEHICLE as c_int
            {
                // doors don't open for vehicles
                return;
            }

            if !(*other).client.is_null()
                && (*other).s.number < MAX_CLIENTS as c_int
                && (*((*other).client as *mut gclient_t)).ps.m_iVehicleNum != 0
            {
                // can't open a door while on a vehicle
                return;
            }
        }

        if (*ent).flags & crate::entity::flags::FL_INACTIVE != 0 {
            return;
        }

        if (*parent).spawnflags & MOVER_LOCKED != 0 {
            // don't even try to use the door if it's locked
            if (*parent).alliedTeam == 0
                || (*other).client.is_null()
                || (*((*other).client as *mut gclient_t)).sess.sessionTeam != (*parent).alliedTeam
            {
                return;
            } else {
                // temporarily unlock us while we call Use_BinaryMover (so it
                // doesn't unlock all the doors in this team)
                if (*parent).flags & crate::entity::flags::FL_TEAMSLAVE != 0 {
                    relock_ent = match (*parent).teammaster {
                        Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
                        None => core::ptr::null_mut(),
                    };
                } else {
                    relock_ent =
                        crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).parent);
                }
                if !relock_ent.is_null() {
                    (*relock_ent).spawnflags &= !MOVER_LOCKED;
                }
            }
        }

        if (*parent).moverState != MOVER_1TO2 {
            // door is not already opening — if closed, opening or open, check this
            Use_BinaryMover(
                ctx,
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).parent),
                ent,
                other,
            );
        }
        if !relock_ent.is_null() {
            // re-lock us
            (*relock_ent).spawnflags |= MOVER_LOCKED;
        }
    }
}

/// Raven `Think_SpawnNewDoorTrigger`.
///
/// All of the parts of a door have been spawned, so create a trigger that
/// encloses all of them.
/// Source: `oracle/oracle/codemp/game/g_mover.c:1168-1215`
pub fn Think_SpawnNewDoorTrigger(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        // set all of the slaves as shootable
        if (*ent).takedamage != 0 {
            let mut other = ent;
            while !other.is_null() {
                (*other).takedamage = qtrue;
                other = crate::ent_id::resolve(
                    (*ctx.world).g_entities.as_mut_ptr(),
                    (*other).teamchain,
                );
            }
        }

        // find the bounds of everything on the team
        let mut mins = (*ent).r.absmin;
        let mut maxs = (*ent).r.absmax;

        let mut other = match (*ent).teamchain {
            Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
            None => core::ptr::null_mut(),
        };
        while !other.is_null() {
            AddPointToBounds((*other).r.absmin, &mut mins, &mut maxs);
            AddPointToBounds((*other).r.absmax, &mut mins, &mut maxs);
            other = match (*other).teamchain {
                Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
                None => core::ptr::null_mut(),
            };
        }

        // find the thinnest axis, which will be the one we expand
        let mut best = 0usize;
        for i in 1..3 {
            if maxs[i] - mins[i] < maxs[best] - mins[best] {
                best = i;
            }
        }
        maxs[best] += 120.0;
        mins[best] -= 120.0;

        // create a trigger with this size
        let other = G_Spawn(ctx);
        (*other).r.mins = mins;
        (*other).r.maxs = maxs;
        (*other).parent = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), ent);
        (*other).r.contents = CONTENTS_TRIGGER;
        (*other).touch = Some(EntTouch::Touch_DoorTrigger).into();
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(other));
        (*other).classname = c"trigger_door".as_ptr() as *mut c_char;
        // remember the thinnest axis
        (*other).count = best as c_int;

        MatchTeam(ctx, ent, (*ent).moverState, (*ctx.world).level.time);
    }
}

/// Raven `Think_MatchTeam`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1217-1220`
pub fn Think_MatchTeam(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        MatchTeam(ctx, ent, (*ent).moverState, (*ctx.world).level.time);
    }
}

/// Raven `G_EntIsDoor`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1222-1237`
pub fn G_EntIsDoor(ctx: GameContext<'_>, entityNum: c_int) -> qboolean {
    unsafe {
        if entityNum < 0 || entityNum >= ENTITYNUM_WORLD {
            return qfalse;
        }

        let ent = &mut (*ctx.world).g_entities[entityNum as usize] as *mut gentity_t;
        if crate::q_shared::Q_stricmp((*ent).classname, c"func_door".as_ptr()) == 0 {
            // blocked by a door
            return qtrue;
        }
        qfalse
    }
}

/// Raven `G_FindDoorTrigger`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1239-1280`
pub fn G_FindDoorTrigger(ctx: GameContext<'_>, ent: *mut gentity_t) -> *mut gentity_t {
    unsafe {
        let mut owner: *mut gentity_t = core::ptr::null_mut();
        let mut door = ent;
        if (*door).flags & crate::entity::flags::FL_TEAMSLAVE != 0 {
            // not the master door, get the master door
            while !(*door).teammaster.is_none()
                && (*door).flags & crate::entity::flags::FL_TEAMSLAVE != 0
            {
                door = crate::ent_id::resolve(
                    (*ctx.world).g_entities.as_mut_ptr(),
                    (*door).teammaster,
                );
            }
        }
        if !(*door).targetname.is_null() {
            // find out what is targeting it
            loop {
                owner = G_Find(
                    ctx,
                    owner,
                    core::mem::offset_of!(gentity_t, target) as c_int,
                    (*door).targetname,
                );
                if owner.is_null() {
                    break;
                }
                if (*owner).r.contents & CONTENTS_TRIGGER != 0 {
                    return owner;
                }
            }
            owner = core::ptr::null_mut();
            loop {
                owner = G_Find(
                    ctx,
                    owner,
                    core::mem::offset_of!(gentity_t, target2) as c_int,
                    (*door).targetname,
                );
                if owner.is_null() {
                    break;
                }
                if (*owner).r.contents & CONTENTS_TRIGGER != 0 {
                    return owner;
                }
            }
        }

        owner = core::ptr::null_mut();
        loop {
            owner = G_Find(
                ctx,
                owner,
                core::mem::offset_of!(gentity_t, classname) as c_int,
                c"trigger_door".as_ptr(),
            );
            if owner.is_null() {
                break;
            }
            if crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*owner).parent) == door
            {
                return owner;
            }
        }

        core::ptr::null_mut()
    }
}

/// Raven `G_EntIsUnlockedDoor`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1282-1346`
pub fn G_EntIsUnlockedDoor(ctx: GameContext<'_>, entityNum: c_int) -> qboolean {
    unsafe {
        if entityNum < 0 || entityNum >= ENTITYNUM_WORLD {
            return qfalse;
        }

        if G_EntIsDoor(ctx, entityNum) != 0 {
            let mut ent = &mut (*ctx.world).g_entities[entityNum as usize] as *mut gentity_t;
            let mut owner: *mut gentity_t;
            if (*ent).flags & crate::entity::flags::FL_TEAMSLAVE != 0 {
                // not the master door, get the master door
                while !(*ent).teammaster.is_none()
                    && (*ent).flags & crate::entity::flags::FL_TEAMSLAVE != 0
                {
                    ent = crate::ent_id::resolve(
                        (*ctx.world).g_entities.as_mut_ptr(),
                        (*ent).teammaster,
                    );
                }
            }
            if !(*ent).targetname.is_null() {
                // find out what is targeting it
                owner = core::ptr::null_mut();
                loop {
                    owner = G_Find(
                        ctx,
                        owner,
                        core::mem::offset_of!(gentity_t, target) as c_int,
                        (*ent).targetname,
                    );
                    if owner.is_null() {
                        break;
                    }
                    if crate::q_shared::Q_stricmp((*owner).classname, c"trigger_multiple".as_ptr())
                        == 0
                        && (*owner).flags & crate::entity::flags::FL_INACTIVE == 0
                    {
                        return qtrue;
                    }
                }
                owner = core::ptr::null_mut();
                loop {
                    owner = G_Find(
                        ctx,
                        owner,
                        core::mem::offset_of!(gentity_t, target2) as c_int,
                        (*ent).targetname,
                    );
                    if owner.is_null() {
                        break;
                    }
                    if crate::q_shared::Q_stricmp((*owner).classname, c"trigger_multiple".as_ptr())
                        == 0
                        && (*owner).flags & crate::entity::flags::FL_INACTIVE == 0
                    {
                        return qtrue;
                    }
                }
                return qfalse;
            } else {
                // check the door's auto-created trigger instead
                owner = G_FindDoorTrigger(ctx, ent);
                if !owner.is_null() && (*owner).flags & crate::entity::flags::FL_INACTIVE != 0 {
                    // owning auto-created trigger is inactive
                    return qfalse;
                }
            }
            if (*ent).flags & crate::entity::flags::FL_INACTIVE == 0
                && (*ent).health == 0
                && (*ent).spawnflags & MOVER_PLAYER_USE == 0
                && (*ent).spawnflags & MOVER_FORCE_ACTIVATE == 0
                && (*ent).spawnflags & MOVER_LOCKED == 0
            {
                return qtrue;
            }
        }
        qfalse
    }
}

/// Raven `SP_func_door`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1380-1472`
pub fn SP_func_door(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        G_SpawnInt(
            ctx,
            c"vehopen".as_ptr(),
            c"0".as_ptr(),
            &mut (*ent).genericValue14 as *mut c_int,
        );

        (*ent).blocked = Some(EntBlocked::Blocked_Door).into();

        // default speed of 400
        if (*ent).speed == 0.0 {
            (*ent).speed = 400.0;
        }

        // default wait of 2 seconds
        if (*ent).wait == 0.0 {
            (*ent).wait = 2.0;
        }
        (*ent).wait *= 1000.0;

        (*ent).delay *= 1000;

        // default lip of 8 units
        let mut lip = 0.0f32;
        G_SpawnFloat(ctx, c"lip".as_ptr(), c"8".as_ptr(), &mut lip as *mut f32);

        // default damage of 2 points
        G_SpawnInt(
            ctx,
            c"dmg".as_ptr(),
            c"2".as_ptr(),
            &mut (*ent).damage as *mut c_int,
        );
        if (*ent).damage < 0 {
            (*ent).damage = 0;
        }

        G_SpawnInt(
            ctx,
            c"teamallow".as_ptr(),
            c"0".as_ptr(),
            &mut (*ent).alliedTeam as *mut c_int,
        );

        // first position at start
        (*ent).pos1 = (*ent).s.origin;

        // calculate second position
        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );
        G_SetMovedir(&mut (*ent).s.angles, &mut (*ent).movedir);
        let abs_movedir = [
            (*ent).movedir[0].abs(),
            (*ent).movedir[1].abs(),
            (*ent).movedir[2].abs(),
        ];
        let size = [
            (*ent).r.maxs[0] - (*ent).r.mins[0],
            (*ent).r.maxs[1] - (*ent).r.mins[1],
            (*ent).r.maxs[2] - (*ent).r.mins[2],
        ];
        let distance =
            (abs_movedir[0] * size[0] + abs_movedir[1] * size[1] + abs_movedir[2] * size[2]) - lip;
        for i in 0..3 {
            (*ent).pos2[i] = (*ent).pos1[i] + distance * (*ent).movedir[i];
        }

        // if "start_open", reverse position 1 and 2
        if (*ent).spawnflags & 1 != 0 {
            let temp = (*ent).pos2;
            (*ent).pos2 = (*ent).s.origin;
            (*ent).pos1 = temp;
        }

        if (*ent).spawnflags & MOVER_LOCKED != 0 {
            //a locked door, set up as locked until used directly
            (*ent).s.eFlags |= EF_SHADER_ANIM; // use frame-controlled shader anim
            (*ent).s.frame = 0; // first stage of anim
        }
        InitMover(ctx, ent);

        (*ent).nextthink = (*ctx.world).level.time + FRAMETIME;

        if (*ent).flags & crate::entity::flags::FL_TEAMSLAVE == 0 {
            let mut health = 0;
            G_SpawnInt(
                ctx,
                c"health".as_ptr(),
                c"0".as_ptr(),
                &mut health as *mut c_int,
            );

            if health != 0 {
                (*ent).takedamage = qtrue;
            }

            if (*ent).spawnflags & MOVER_LOCKED == 0
                && (!(*ent).targetname.is_null()
                    || health != 0
                    || (*ent).spawnflags & MOVER_PLAYER_USE != 0
                    || (*ent).spawnflags & MOVER_FORCE_ACTIVATE != 0)
            {
                // non touch/shoot doors
                (*ent).think = Some(EntThink::Think_MatchTeam).into();

                if (*ent).spawnflags & MOVER_FORCE_ACTIVATE != 0 {
                    // so we know it's push/pullable on the client
                    (*ent).s.bolt1 = 1;
                }
            } else {
                // locked doors still spawn a trigger
                (*ent).think = Some(EntThink::Think_SpawnNewDoorTrigger).into();
            }
        }
    }
}

/// Raven `Touch_Plat`.
///
/// Don't allow decent if a living player is on it.
/// Source: `oracle/oracle/codemp/game/g_mover.c:1489-1498`
pub fn Touch_Plat(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    trace: *mut trace_t,
) {
    unsafe {
        if (*other).client.is_null()
            || (*((*other).client as *mut gclient_t)).ps.stats[statIndex_t::STAT_HEALTH as usize]
                <= 0
        {
            return;
        }

        // delay return-to-pos1 by one second
        if (*ent).moverState == MOVER_POS2 {
            (*ent).nextthink = (*ctx.world).level.time + 1000;
        }
    }
}

/// Raven `Touch_PlatCenterTrigger`.
///
/// If the plat is at the bottom position, start it going up.
/// Source: `oracle/oracle/codemp/game/g_mover.c:1507-1515`
pub fn Touch_PlatCenterTrigger(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    trace: *mut trace_t,
) {
    unsafe {
        if (*other).client.is_null() {
            return;
        }

        let parent = match (*ent).parent {
            Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
            None => core::ptr::null_mut(),
        };
        if (*parent).moverState == MOVER_POS1 {
            Use_BinaryMover(
                ctx,
                crate::ent_id::resolve((*ctx.world).g_entities.as_mut_ptr(), (*ent).parent),
                ent,
                other,
            );
        }
    }
}

/// Raven `SpawnPlatTrigger`.
///
/// Spawn a trigger in the middle of the plat's low position. Elevator cars
/// require that the trigger extend through the entire low position, not
/// just sit on top of it.
/// Source: `oracle/oracle/codemp/game/g_mover.c:1527-1559`
pub fn SpawnPlatTrigger(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        // the middle trigger will be a thin trigger just above the starting
        // position
        let trigger = G_Spawn(ctx);
        (*trigger).touch = Some(EntTouch::Touch_PlatCenterTrigger).into();
        (*trigger).r.contents = CONTENTS_TRIGGER;
        (*trigger).parent = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), ent);

        let mut tmin = [0.0f32; 3];
        let mut tmax = [0.0f32; 3];
        tmin[0] = (*ent).pos1[0] + (*ent).r.mins[0] + 33.0;
        tmin[1] = (*ent).pos1[1] + (*ent).r.mins[1] + 33.0;
        tmin[2] = (*ent).pos1[2] + (*ent).r.mins[2];

        tmax[0] = (*ent).pos1[0] + (*ent).r.maxs[0] - 33.0;
        tmax[1] = (*ent).pos1[1] + (*ent).r.maxs[1] - 33.0;
        tmax[2] = (*ent).pos1[2] + (*ent).r.maxs[2] + 8.0;

        if tmax[0] <= tmin[0] {
            tmin[0] = (*ent).pos1[0] + ((*ent).r.mins[0] + (*ent).r.maxs[0]) * 0.5;
            tmax[0] = tmin[0] + 1.0;
        }
        if tmax[1] <= tmin[1] {
            tmin[1] = (*ent).pos1[1] + ((*ent).r.mins[1] + (*ent).r.maxs[1]) * 0.5;
            tmax[1] = tmin[1] + 1.0;
        }

        (*trigger).r.mins = tmin;
        (*trigger).r.maxs = tmax;

        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(trigger));
    }
}

/// Raven `SP_func_plat`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1576-1617`
pub fn SP_func_plat(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        (*ent).s.angles = [0.0; 3];

        G_SpawnFloat(
            ctx,
            c"speed".as_ptr(),
            c"200".as_ptr(),
            &mut (*ent).speed as *mut f32,
        );
        G_SpawnInt(
            ctx,
            c"dmg".as_ptr(),
            c"2".as_ptr(),
            &mut (*ent).damage as *mut c_int,
        );
        G_SpawnFloat(
            ctx,
            c"wait".as_ptr(),
            c"1".as_ptr(),
            &mut (*ent).wait as *mut f32,
        );
        let mut lip = 0.0f32;
        G_SpawnFloat(ctx, c"lip".as_ptr(), c"8".as_ptr(), &mut lip as *mut f32);

        (*ent).wait = 1000.0;

        // create second position
        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );

        let mut height = 0.0f32;
        if G_SpawnFloat(
            ctx,
            c"height".as_ptr(),
            c"0".as_ptr(),
            &mut height as *mut f32,
        ) == 0
        {
            height = ((*ent).r.maxs[2] - (*ent).r.mins[2]) - lip;
        }

        // pos1 is the rest (bottom) position, pos2 is the top
        (*ent).pos2 = (*ent).s.origin;
        (*ent).pos1 = (*ent).pos2;
        (*ent).pos1[2] -= height;

        InitMover(ctx, ent);

        // touch function keeps the plat from returning while a live player
        // is standing on it
        (*ent).touch = Some(EntTouch::Touch_Plat).into();

        (*ent).blocked = Some(EntBlocked::Blocked_Door).into();

        (*ent).parent = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), ent); // so it can be treated as a door

        // spawn the trigger if one hasn't been custom made
        if (*ent).targetname.is_null() {
            SpawnPlatTrigger(ctx, ent);
        }
    }
}

/// Raven `Touch_Button`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1633-1641`
pub fn Touch_Button(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    trace: *mut trace_t,
) {
    unsafe {
        if (*other).client.is_null() {
            return;
        }

        if (*ent).moverState == MOVER_POS1 {
            Use_BinaryMover(ctx, ent, other, other);
        }
    }
}

/// Raven `SP_func_button`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1660-1702`
pub fn SP_func_button(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        if (*ent).speed == 0.0 {
            (*ent).speed = 40.0;
        }

        if (*ent).wait == 0.0 {
            (*ent).wait = 1.0;
        }
        (*ent).wait *= 1000.0;

        // first position
        (*ent).pos1 = (*ent).s.origin;

        // calculate second position
        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );

        let mut lip = 0.0f32;
        G_SpawnFloat(ctx, c"lip".as_ptr(), c"4".as_ptr(), &mut lip as *mut f32);

        G_SetMovedir(&mut (*ent).s.angles, &mut (*ent).movedir);
        let abs_movedir = [
            (*ent).movedir[0].abs(),
            (*ent).movedir[1].abs(),
            (*ent).movedir[2].abs(),
        ];
        let size = [
            (*ent).r.maxs[0] - (*ent).r.mins[0],
            (*ent).r.maxs[1] - (*ent).r.mins[1],
            (*ent).r.maxs[2] - (*ent).r.mins[2],
        ];
        let distance =
            abs_movedir[0] * size[0] + abs_movedir[1] * size[1] + abs_movedir[2] * size[2] - lip;
        for i in 0..3 {
            (*ent).pos2[i] = (*ent).pos1[i] + distance * (*ent).movedir[i];
        }

        if (*ent).health != 0 {
            // shootable button
            (*ent).takedamage = qtrue;
        } else {
            // touchable button
            (*ent).touch = Some(EntTouch::Touch_Button).into();
        }

        InitMover(ctx, ent);
    }
}

/// Raven `Think_BeginMoving`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1727-1732`
pub fn Think_BeginMoving(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        G_PlayDoorSound(ctx, ent, BMS_START);
        G_PlayDoorLoopSound(ctx, ent);
        (*ent).s.pos.trTime = (*ctx.world).level.time;
        (*ent).s.pos.trType = trType_t::TR_LINEAR_STOP;
    }
}

/// Raven `Reached_Train`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1739-1793`
pub fn Reached_Train(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        // copy the appropriate values
        let next = match (*ent).nextTrain {
            Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
            None => return, // just stop
        };
        if (*next).nextTrain.is_none() {
            return; // just stop
        }

        // fire all other targets
        G_UseTargets(ctx, next, core::ptr::null_mut());

        // set the new trajectory
        (*ent).nextTrain = (*next).nextTrain;
        (*ent).pos1 = (*next).s.origin;
        let next_next =
            &mut (*ctx.world).g_entities[(*next).nextTrain.unwrap().index()] as *mut gentity_t;
        (*ent).pos2 = (*next_next).s.origin;

        // if the path_corner has a speed, use that
        let mut speed = if (*next).speed != 0.0 {
            (*next).speed
        } else {
            (*ent).speed
        };
        if speed < 1.0 {
            speed = 1.0;
        }

        // calculate duration
        let r#move = [
            (*ent).pos2[0] - (*ent).pos1[0],
            (*ent).pos2[1] - (*ent).pos1[1],
            (*ent).pos2[2] - (*ent).pos1[2],
        ];
        // Raven uses VectorLength (double sqrt narrowed to float); an inline f32 sqrt
        // double-rounds and diverges from the oracle.
        let length = VectorLength(r#move);

        (*ent).s.pos.trDuration = (length * 1000.0 / speed) as c_int;

        // start it going
        SetMoverState(ctx, ent, MOVER_1TO2, (*ctx.world).level.time);

        G_PlayDoorSound(ctx, ent, BMS_END);

        // if there is a "wait" value on the target, don't start moving yet
        if (*next).wait != 0.0 {
            (*ent).s.loopSound = 0;
            (*ent).s.loopIsSoundset = qfalse;
            (*ent).nextthink = (*ctx.world).level.time + ((*next).wait * 1000.0) as c_int;
            (*ent).think = Some(EntThink::Think_BeginMoving).into();
            (*ent).s.pos.trType = trType_t::TR_STATIONARY;
        } else {
            G_PlayDoorLoopSound(ctx, ent);
        }
    }
}

/// Raven `Think_SetupTrainTargets`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1802-1864`
pub fn Think_SetupTrainTargets(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        (*ent).nextTrain = ent_id_opt(
            (*ctx.world).g_entities.as_mut_ptr(),
            G_Find(
                ctx,
                core::ptr::null_mut(),
                core::mem::offset_of!(gentity_t, targetname) as c_int,
                (*ent).target,
            ),
        );
        if (*ent).nextTrain.is_none() {
            Com_Printf(c"func_train at %s with an unfound target\n".as_ptr());
            // Free me?`
            return;
        }

        // FIXME: this can go into an infinite loop if last path_corner doesn't
        // link to first path_corner, like so:
        //  t1---->t2---->t3
        //          ^      |
        //           \_____|
        let mut start: *mut gentity_t = core::ptr::null_mut();
        let mut path = match (*ent).nextTrain {
            Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
            None => core::ptr::null_mut(),
        };
        while path != start {
            if start.is_null() {
                start = path;
            }

            if (*path).target.is_null() {
                // end of path
                break;
            }

            // find a path_corner among the targets — there may also be
            // other targets that get fired when the corner is reached
            let mut next: *mut gentity_t;
            loop {
                next = G_Find(
                    ctx,
                    core::ptr::null_mut(),
                    core::mem::offset_of!(gentity_t, targetname) as c_int,
                    (*path).target,
                );
                if next.is_null() {
                    // end of path
                    break;
                }
                // Raven uses libc `strcmp` (case-sensitive) here, which has no
                // ported binding in this crate; `Q_stricmp` is the closest
                // available equivalent (case-insensitive) and is a no-op
                // difference for the literal "path_corner" classname.
                if crate::q_shared::Q_stricmp((*next).classname, c"path_corner".as_ptr()) == 0 {
                    break;
                }
            }

            if !next.is_null() {
                (*path).nextTrain = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), next);
            } else {
                break;
            }

            path = next;
        }

        if (*ent).targetname.is_null() || ((*ent).spawnflags & 1) != 0
        /* start on */
        {
            // start the train moving from the first corner
            Reached_Train(ctx, ent);
        } else {
            G_SetOrigin(ent, (*ent).s.origin);
        }
    }
}

/// Raven `SP_path_corner`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1873-1880`
pub fn SP_path_corner(ctx: GameContext<'_>, self_: *mut gentity_t) {
    unsafe {
        if (*self_).targetname.is_null() {
            G_Printf(ctx, c"path_corner with no targetname at %s\n".as_ptr());
            let _ = vtos(ctx, (*self_).s.origin);
            G_FreeEntity(ctx, self_);
            return;
        }
        // path corners don't need to be linked in
    }
}

/// Raven `SP_func_train`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1897-1927`
pub fn SP_func_train(ctx: GameContext<'_>, self_: *mut gentity_t) {
    unsafe {
        (*self_).s.angles = [0.0; 3];

        // Raven `TRAIN_BLOCK_STOPS` spawnflag (`g_mover.c:1900`); not yet a
        // named const anywhere in the crate graph — transcribed as its
        // literal bit here (single call site, no cross-file reuse to justify
        // a shared const yet).
        pub const TRAIN_BLOCK_STOPS: c_int = 1;
        if (*self_).spawnflags & TRAIN_BLOCK_STOPS != 0 {
            (*self_).damage = 0;
        } else if (*self_).damage == 0 {
            (*self_).damage = 2;
        }

        if (*self_).speed == 0.0 {
            (*self_).speed = 100.0;
        }

        if (*self_).target.is_null() {
            let _ = vtos(ctx, (*self_).r.absmin);
            G_Printf(ctx, c"func_train without a target at %s\n".as_ptr());
            G_FreeEntity(ctx, self_);
            return;
        }

        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(self_, std::ffi::CStr::from_ptr((*self_).model).to_owned()),
        );
        InitMover(ctx, self_);

        (*self_).reached = Some(EntReached::Reached_Train).into();

        // start trains on the second frame, to make sure their targets have
        // had a chance to spawn
        (*self_).nextthink = (*ctx.world).level.time + FRAMETIME;
        (*self_).think = Some(EntThink::Think_SetupTrainTargets).into();
    }
}

/// Raven `SP_func_static`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:1956-2019`
pub fn SP_func_static(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );

        (*ent).pos1 = (*ent).s.origin;
        (*ent).pos2 = (*ent).s.origin;

        InitMover(ctx, ent);

        (*ent).use_ = Some(EntUse::func_static_use).into();
        (*ent).reached = FnId::NONE;

        G_SetOrigin(ent, (*ent).s.origin);
        G_SetAngles(ent, (*ent).s.angles);

        if (*ent).spawnflags & 2048 != 0 {
            // yes this is very very evil, but for now (pre-alpha) it's a
            // solution — I need to rotate something that is huge and it's
            // touching too many area portals...
            (*ent).r.svFlags |= SVF_BROADCAST;
        }

        if (*ent).spawnflags & 4 != 0 {
            // SWITCH_SHADER
            (*ent).s.eFlags |= EF_SHADER_ANIM; // use frame-controlled shader anim
            (*ent).s.frame = 0; // first stage of anim
        }

        if (*ent).spawnflags & 1 != 0 || (*ent).spawnflags & 2 != 0 {
            // so we know it's push/pullable on the client
            (*ent).s.bolt1 = 1;
        }

        G_SpawnInt(
            ctx,
            c"model2scale".as_ptr(),
            c"0".as_ptr(),
            &mut (*ent).s.iModelScale as *mut c_int,
        );
        if (*ent).s.iModelScale < 0 {
            // NOTE: -1 scale is x -100% (so -3 is 300%)
            (*ent).s.legsFlip = qtrue;
            (*ent).s.iModelScale = -(*ent).s.iModelScale;
        } else if (*ent).s.iModelScale > 1023 {
            (*ent).s.iModelScale = 1023;
        }

        let mut test = 0;
        G_SpawnInt(
            ctx,
            c"hyperspace".as_ptr(),
            c"0".as_ptr(),
            &mut test as *mut c_int,
        );
        if test != 0 {
            (*ent).r.svFlags |= SVF_BROADCAST;
            (*ent).s.eFlags2 |= EF2_HYPERSPACE;
        }

        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));

        if (*ctx.world).level.mBSPInstanceDepth != 0 {
            // this means that this guy will never be updated, moved, changed, etc.
            (*ent).s.eFlags = EF_PERMANENT;
        }
    }
}

/// Raven `func_static_use`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2021-2030`
pub fn func_static_use(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        G_ActivateBehavior(ctx, self_, bSet_t::BSET_USE as c_int);

        if (*self_).spawnflags & 4 /* SWITCH_SHADER */ != 0 {
            (*self_).s.frame = if (*self_).s.frame != 0 { 0 } else { 1 }; // toggle frame
        }
        G_UseTargets(ctx, self_, activator);
    }
}

/// Raven `func_rotating_use`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2040-2066`
pub fn func_rotating_use(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        if (*self_).s.apos.trType == trType_t::TR_LINEAR {
            (*self_).s.apos.trType = trType_t::TR_STATIONARY;
            // stop the sound if it stops moving
            (*self_).s.loopSound = 0;
            (*self_).s.loopIsSoundset = qfalse;
            // play stop sound too?
            if !(*self_).soundSet.is_null() && *(*self_).soundSet != 0 {
                (*self_).s.soundSetIndex = G_SoundSetIndex(ctx, (*self_).soundSet);
                G_AddEvent(self_, entity_event_t::EV_BMODEL_SOUND as c_int, BMS_END);
            }
        } else {
            if !(*self_).soundSet.is_null() && *(*self_).soundSet != 0 {
                (*self_).s.soundSetIndex = G_SoundSetIndex(ctx, (*self_).soundSet);
                G_AddEvent(self_, entity_event_t::EV_BMODEL_SOUND as c_int, BMS_START);
                (*self_).s.loopSound = BMS_MID;
                (*self_).s.loopIsSoundset = qtrue;
            }
            (*self_).s.apos.trType = trType_t::TR_LINEAR;
        }
    }
}

/// Raven `SP_func_rotating`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2133-2209`
pub fn SP_func_rotating(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let mut spinangles: vec3_t = [0.0; 3];
        if (*ent).health != 0 {
            let sav_spawnflags = (*ent).spawnflags;
            (*ent).spawnflags = 0;
            SP_func_breakable(ctx, ent);
            (*ent).spawnflags = sav_spawnflags;
        } else {
            trap::SetBrushModel(
                ctx.engine,
                GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
            );
            InitMover(ctx, ent);

            (*ent).s.pos.trBase = (*ent).s.origin;
            (*ent).r.currentOrigin = (*ent).s.pos.trBase;
            (*ent).r.currentAngles = (*ent).s.apos.trBase;

            trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
        }

        G_SpawnInt(
            ctx,
            c"model2scale".as_ptr(),
            c"0".as_ptr(),
            &mut (*ent).s.iModelScale as *mut c_int,
        );
        if (*ent).s.iModelScale < 0 {
            (*ent).s.legsFlip = qtrue;
            (*ent).s.iModelScale = -(*ent).s.iModelScale;
        } else if (*ent).s.iModelScale > 1023 {
            (*ent).s.iModelScale = 1023;
        }

        if G_SpawnVector(
            ctx,
            c"spinangles".as_ptr(),
            c"0 0 0".as_ptr(),
            spinangles.as_mut_ptr(),
        ) != 0
        {
            (*ent).speed = (spinangles[0] * spinangles[0]
                + spinangles[1] * spinangles[1]
                + spinangles[2] * spinangles[2])
                .sqrt();
            // set the axis of rotation
            (*ent).s.apos.trDelta = spinangles;
        } else {
            if (*ent).speed == 0.0 {
                (*ent).speed = 100.0;
            }
            // set the axis of rotation
            if (*ent).spawnflags & 4 != 0 {
                (*ent).s.apos.trDelta[2] = (*ent).speed;
            } else if (*ent).spawnflags & 8 != 0 {
                (*ent).s.apos.trDelta[0] = (*ent).speed;
            } else {
                (*ent).s.apos.trDelta[1] = (*ent).speed;
            }
        }
        (*ent).s.apos.trType = trType_t::TR_LINEAR;

        if (*ent).damage == 0 {
            if (*ent).spawnflags & 16 != 0 {
                // IMPACT
                (*ent).damage = 10000;
            } else {
                (*ent).damage = 2;
            }
        }
        if (*ent).spawnflags & 2 != 0 {
            // RADAR: show up on Radar at close range and play impact sound
            // when close...? Range based on my size
            (*ent).s.speed = Distance((*ent).r.absmin, (*ent).r.absmax) * 0.5;
            (*ent).s.eFlags |= EF_RADAROBJECT;
        }
    }
}

/// Raven `SP_func_bobbing`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2231-2258`
pub fn SP_func_bobbing(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let mut height = 0.0f32;
        let mut phase = 0.0f32;

        G_SpawnFloat(
            ctx,
            c"speed".as_ptr(),
            c"4".as_ptr(),
            &mut (*ent).speed as *mut f32,
        );
        G_SpawnFloat(
            ctx,
            c"height".as_ptr(),
            c"32".as_ptr(),
            &mut height as *mut f32,
        );
        G_SpawnInt(
            ctx,
            c"dmg".as_ptr(),
            c"2".as_ptr(),
            &mut (*ent).damage as *mut c_int,
        );
        G_SpawnFloat(
            ctx,
            c"phase".as_ptr(),
            c"0".as_ptr(),
            &mut phase as *mut f32,
        );

        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );
        InitMover(ctx, ent);

        (*ent).s.pos.trBase = (*ent).s.origin;
        (*ent).r.currentOrigin = (*ent).s.origin;

        (*ent).s.pos.trDuration = ((*ent).speed * 1000.0) as c_int;
        (*ent).s.pos.trTime = ((*ent).s.pos.trDuration as f32 * phase) as c_int;
        (*ent).s.pos.trType = trType_t::TR_SINE;

        // set the axis of bobbing
        if (*ent).spawnflags & 1 != 0 {
            (*ent).s.pos.trDelta[0] = height;
        } else if (*ent).spawnflags & 2 != 0 {
            (*ent).s.pos.trDelta[1] = height;
        } else {
            (*ent).s.pos.trDelta[2] = height;
        }
    }
}

/// Raven `SP_func_pendulum`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2280-2313`
pub fn SP_func_pendulum(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let mut speed = 0.0f32;
        let mut phase = 0.0f32;

        G_SpawnFloat(
            ctx,
            c"speed".as_ptr(),
            c"30".as_ptr(),
            &mut speed as *mut f32,
        );
        G_SpawnInt(
            ctx,
            c"dmg".as_ptr(),
            c"2".as_ptr(),
            &mut (*ent).damage as *mut c_int,
        );
        G_SpawnFloat(
            ctx,
            c"phase".as_ptr(),
            c"0".as_ptr(),
            &mut phase as *mut f32,
        );

        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );

        // find pendulum length
        let mut length = (*ent).r.mins[2].abs();
        if length < 8.0 {
            length = 8.0;
        }

        // Raven: `1 / ( M_PI * 2 ) * sqrt( g_gravity.value / ( 3 * length ) )`. The ratio
        // is a float divide, but sqrt is the double libm call and 1/(M_PI*2) is double;
        // the product narrows to float.
        let ratio = (*ctx.world).cvars.g_gravity.value / (3.0 * length);
        let freq = (1.0f64 / (core::f64::consts::PI * 2.0) * (ratio as f64).sqrt()) as f32;

        (*ent).s.pos.trDuration = (1000.0 / freq) as c_int;

        InitMover(ctx, ent);

        (*ent).s.pos.trBase = (*ent).s.origin;
        (*ent).r.currentOrigin = (*ent).s.origin;

        (*ent).s.apos.trBase = (*ent).s.angles;

        (*ent).s.apos.trDuration = (1000.0 / freq) as c_int;
        (*ent).s.apos.trTime = ((*ent).s.apos.trDuration as f32 * phase) as c_int;
        (*ent).s.apos.trType = trType_t::TR_SINE;
        (*ent).s.apos.trDelta[2] = speed;
    }
}

/// Raven `CacheChunkEffects`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2323-2361`
pub fn CacheChunkEffects(ctx: GameContext<'_>, material: material_t) {
    match material {
        MAT_GLASS => {
            G_EffectIndex(c"chunks/glassbreak".as_ptr());
        }
        MAT_GLASS_METAL => {
            G_EffectIndex(c"chunks/glassbreak".as_ptr());
            G_EffectIndex(c"chunks/metalexplode".as_ptr());
        }
        MAT_ELECTRICAL | MAT_ELEC_METAL => {
            G_EffectIndex(c"chunks/sparkexplode".as_ptr());
        }
        MAT_METAL | MAT_METAL2 | MAT_METAL3 | MAT_CRATE1 | MAT_CRATE2 => {
            G_EffectIndex(c"chunks/metalexplode".as_ptr());
        }
        MAT_GRATE1 => {
            G_EffectIndex(c"chunks/grateexplode".as_ptr());
        }
        MAT_DRK_STONE | MAT_LT_STONE | MAT_GREY_STONE | MAT_WHITE_METAL | MAT_SNOWY_ROCK => {
            G_EffectIndex(c"chunks/rockbreaklg".as_ptr());
            G_EffectIndex(c"chunks/rockbreakmed".as_ptr());
        }
        MAT_ROPE => {
            G_EffectIndex(c"chunks/ropebreak".as_ptr());
        }
        _ => {}
    }
}

/// Raven `G_MiscModelExplosion`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2363-2377`
pub fn G_MiscModelExplosion(
    ctx: GameContext<'_>,
    mins: vec3_t,
    maxs: vec3_t,
    size: c_int,
    chunkType: material_t,
) {
    unsafe {
        let mid = [
            (mins[0] + maxs[0]) * 0.5,
            (mins[1] + maxs[1]) * 0.5,
            (mins[2] + maxs[2]) * 0.5,
        ];

        let te = G_TempEntity(ctx, mid, entity_event_t::EV_MISC_MODEL_EXP as c_int);

        (*te).s.origin2 = maxs;
        (*te).s.angles2 = mins;
        (*te).s.time = size;
        (*te).s.eventParm = chunkType;
    }
}

/// Raven `G_Chunks`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2379-2395`
pub fn G_Chunks(
    ctx: GameContext<'_>,
    owner: c_int,
    origin: vec3_t,
    normal: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
    speed: f32,
    numChunks: c_int,
    chunkType: material_t,
    customChunk: c_int,
    baseScale: f32,
) {
    unsafe {
        let te = G_TempEntity(ctx, origin, entity_event_t::EV_DEBRIS as c_int);

        // Now it's time to cram everything horribly into the entitystate of
        // an event entity.
        (*te).s.owner = owner;
        (*te).s.origin = origin;
        (*te).s.angles = normal;
        (*te).s.origin2 = maxs;
        (*te).s.angles2 = mins;
        (*te).s.speed = speed;
        (*te).s.eventParm = numChunks;
        (*te).s.trickedentindex = chunkType;
        (*te).s.modelindex = customChunk;
        (*te).s.apos.trBase[0] = baseScale;
    }
}

/// Raven `funcBBrushDieGo`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2398-2498`
pub fn funcBBrushDieGo(ctx: GameContext<'_>, self_: *mut gentity_t) {
    unsafe {
        let attacker = (*self_).enemy;
        let chunk_type = (*self_).material;

        // if a missile is stuck to us, blow it up so we don't look dumb
        for i in 0..mp_qshared::shared::MAX_GENTITIES {
            let other = &mut (*ctx.world).g_entities[i] as *mut gentity_t;
            if (*other).s.groundEntityNum == (*self_).s.number
                && (*other).s.eFlags & EF_MISSILE_STICK != 0
            {
                G_Damage(
                    ctx,
                    other,
                    self_,
                    self_,
                    None,
                    [0.0, 0.0, 0.0],
                    99999,
                    0,
                    meansOfDeath_t::MOD_CRUSH as c_int,
                );
            }
        }

        // so chunks don't get stuck inside me
        (*self_).s.solid = 0;
        (*self_).r.contents = 0;
        (*self_).clipmask = 0;
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(self_));

        let up = [0.0f32, 0.0, 1.0];

        if !(*self_).target.is_null() && !attacker.is_none() {
            G_UseTargets(
                ctx,
                self_,
                attacker.map_or(std::ptr::null_mut(), |id| {
                    &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t
                }),
            );
        }

        let org_size = [
            (*self_).r.absmax[0] - (*self_).r.absmin[0],
            (*self_).r.absmax[1] - (*self_).r.absmin[1],
            (*self_).r.absmax[2] - (*self_).r.absmin[2],
        ];

        // Raven `random()` macro == `(rand()&RAND_MAX)/(float)RAND_MAX`.
        let mut num_chunks = ((*ctx.world).bg_state.rng.random() * 6.0 + 18.0) as c_int;

        // this formula really has no logical basis other than the fact
        // that it seemed to be the closest to yielding the results that I
        // wanted. Volume is length * width * height...then break that
        // volume down based on how many chunks we have.
        // Raven: `sqrt( sqrt( org[0]*org[1]*org[2] )) * 1.75f`. Both sqrts are the double
        // libm call and the whole product stays double until it narrows to float on assign.
        let mut scale =
            (((org_size[0] * org_size[1] * org_size[2]) as f64).sqrt().sqrt() * 1.75) as f32;

        let size = if scale > 48.0 {
            2
        } else if scale > 24.0 {
            1
        } else {
            0
        };

        scale /= num_chunks as f32;

        if (*self_).radius > 0.0 {
            // designer wants to scale number of chunks, helpful because the
            // above scale code is far from perfect — I do this after the
            // scale calculation because it seems that the chunk size
            // generally seems to be very close, it's just the number of
            // chunks is a bit weak.
            num_chunks = (num_chunks as f32 * (*self_).radius) as c_int;
        }

        let mut org = [
            (*self_).r.absmin[0] + (*self_).r.absmax[0],
            (*self_).r.absmin[1] + (*self_).r.absmax[1],
            (*self_).r.absmin[2] + (*self_).r.absmax[2],
        ];
        for c in org.iter_mut() {
            *c *= 0.5;
        }

        let dir = if let Some(attacker_id) = attacker {
            let attacker_ptr = &mut (*ctx.world).g_entities[attacker_id.index()] as *mut gentity_t;
            if !(*attacker_ptr).client.is_null() {
                let mut d = [
                    org[0] - (*attacker_ptr).r.currentOrigin[0],
                    org[1] - (*attacker_ptr).r.currentOrigin[1],
                    org[2] - (*attacker_ptr).r.currentOrigin[2],
                ];
                VectorNormalize(&mut d);
                d
            } else {
                up
            }
        } else {
            up
        };

        if (*self_).spawnflags & 2048 == 0 {
            // NO_EXPLOSION — we are allowed to explode
            G_MiscModelExplosion(ctx, (*self_).r.absmin, (*self_).r.absmax, size, chunk_type);
        }

        if (*self_).genericValue15 != 0 {
            // a custom effect to play
            let ang = [0.0f32, 1.0, 0.0];
            G_PlayEffectID((*self_).genericValue15, org, ang);
        }

        if (*self_).splashDamage > 0 && (*self_).splashRadius > 0 {
            // explode
            G_RadiusDamage(
                ctx,
                org,
                self_,
                (*self_).splashDamage as f32,
                (*self_).splashRadius as f32,
                self_,
                core::ptr::null_mut(),
                meansOfDeath_t::MOD_UNKNOWN as c_int,
            );

            let te = G_TempEntity(ctx, org, entity_event_t::EV_GENERAL_SOUND as c_int);
            (*te).s.eventParm = G_SoundIndex(c"sound/weapons/explosions/cargoexplode.wav".as_ptr());
        }

        //FIXME: base numChunks off size?
        G_Chunks(
            ctx,
            (*self_).s.number,
            org,
            dir,
            (*self_).r.absmin,
            (*self_).r.absmax,
            300.0,
            num_chunks,
            chunk_type,
            0,
            scale * (*self_).mass,
        );

        trap::AdjustAreaPortalState(ctx.engine, GAdjustAreaPortalStateArgs::new(self_, qtrue));
        (*self_).think = Some(EntThink::G_FreeEntity).into();
        (*self_).nextthink = (*ctx.world).level.time + 50;
    }
}

/// Raven `funcBBrushDie`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2500-2514`
pub fn funcBBrushDie(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    inflictor: *mut gentity_t,
    attacker: *mut gentity_t,
    damage: c_int,
    r#mod: c_int,
) {
    unsafe {
        (*self_).takedamage = qfalse; // stop chain reaction runaway loops
        (*self_).enemy = ent_id_opt((*ctx.world).g_entities.as_mut_ptr(), attacker);

        if (*self_).delay != 0 {
            (*self_).think = Some(EntThink::funcBBrushDieGo).into();
            (*self_).nextthink =
                (*ctx.world).level.time + ((*self_).delay as f32 * 1000.0).floor() as c_int;
            return;
        }

        funcBBrushDieGo(ctx, self_);
    }
}

/// Raven `funcBBrushUse`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2516-2530`
pub fn funcBBrushUse(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        G_ActivateBehavior(ctx, self_, bSet_t::BSET_USE as c_int);
        if (*self_).spawnflags & 64 != 0 {
            // Using it doesn't break it, makes it use it's targets
            if !(*self_).target.is_null() && *(*self_).target != 0 {
                G_UseTargets(ctx, self_, activator);
            }
        } else {
            funcBBrushDie(
                ctx,
                self_,
                other,
                activator,
                (*self_).health,
                meansOfDeath_t::MOD_UNKNOWN as c_int,
            );
        }
    }
}

/// Raven `funcBBrushPain`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2532-2597`
pub fn funcBBrushPain(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    attacker: *mut gentity_t,
    damage: c_int,
) {
    unsafe {
        if (*self_).painDebounceTime > (*ctx.world).level.time {
            return;
        }

        if !(*self_).paintarget.is_null() && *(*self_).paintarget != 0 {
            if (*self_).activator.is_none() {
                if !attacker.is_null() && (*attacker).inuse != 0 && !(*attacker).client.is_null() {
                    G_UseTargets2(ctx, self_, attacker, (*self_).paintarget);
                }
            } else {
                G_UseTargets2(
                    ctx,
                    self_,
                    crate::ent_id::resolve(
                        (*ctx.world).g_entities.as_mut_ptr(),
                        (*self_).activator,
                    ),
                    (*self_).paintarget,
                );
            }
        }

        G_ActivateBehavior(ctx, self_, bSet_t::BSET_PAIN as c_int);

        if (*self_).material == MAT_DRK_STONE
            || (*self_).material == MAT_LT_STONE
            || (*self_).material == MAT_GREY_STONE
            || (*self_).material == MAT_SNOWY_ROCK
        {
            // size
            let size = [
                (*self_).r.absmax[0] - (*self_).r.absmin[0],
                (*self_).r.absmax[1] - (*self_).r.absmin[1],
                (*self_).r.absmax[2] - (*self_).r.absmin[2],
            ];
            // This formula really has no logical basis other than the fact
            // that it seemed to be the closest to yielding the results that
            // I wanted. Volume is length * width * height...then break
            // that volume down based on how many chunks we have.
            let scale = VectorLength(size) / 100.0;

            // Raven's dead `VectorMA(absmin, 0.5, size, org)` (result overwritten unread) dropped.
            let mut org = [
                (*self_).r.absmin[0] + (*self_).r.absmax[0],
                (*self_).r.absmin[1] + (*self_).r.absmax[1],
                (*self_).r.absmin[2] + (*self_).r.absmax[2],
            ];
            for c in org.iter_mut() {
                *c *= 0.5;
            }

            let dir = if !attacker.is_null() && !(*attacker).client.is_null() {
                let mut d = [
                    (*attacker).r.currentOrigin[0] - org[0],
                    (*attacker).r.currentOrigin[1] - org[1],
                    (*attacker).r.currentOrigin[2] - org[2],
                ];
                VectorNormalize(&mut d);
                d
            } else {
                [0.0, 0.0, 1.0]
            };

            let mut numChunks = (*ctx.world).bg_state.rng.Q_irand(1, 3);
            if (*self_).radius > 0.0 {
                // designer wants to scale number of chunks, helpful because
                // the above scale code is far from perfect — I do this
                // after the scale calculation because it seems that the
                // chunk size generally seems to be very close, it's just
                // the number of chunks is a bit weak.
                numChunks = (numChunks as f32 * (*self_).radius).ceil() as c_int;
            }

            G_Chunks(
                ctx,
                (*self_).s.number,
                org,
                dir,
                (*self_).r.absmin,
                (*self_).r.absmax,
                300.0,
                numChunks,
                (*self_).material,
                0,
                scale * (*self_).mass,
            );
        }

        if (*self_).wait == 0.0 {
            (*self_).pain = FnId::NONE;
            return;
        }

        (*self_).painDebounceTime = (*ctx.world).level.time + (*self_).wait as c_int;
    }
}

/// Raven `InitBBrush`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2599-2661`
pub fn InitBBrush(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        (*ent).pos1 = (*ent).s.origin;

        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );

        (*ent).die = Some(EntDie::funcBBrushDie).into();
        (*ent).flags |= crate::entity::flags::FL_BBRUSH;

        // if the "model2" key is set, use a separate model for drawing, but
        // clip against the brushes
        if !(*ent).model2.is_null() && *(*ent).model2 != 0 {
            (*ent).s.modelindex2 = G_ModelIndex((*ent).model2);
        }

        // if the "color" or "light" keys are set, setup constantLight
        let mut light = 0.0f32;
        let mut color: vec3_t = [0.0; 3];
        let light_set = G_SpawnFloat(
            ctx,
            c"light".as_ptr(),
            c"100".as_ptr(),
            &mut light as *mut f32,
        );
        let color_set = G_SpawnVector(
            ctx,
            c"color".as_ptr(),
            c"1 1 1".as_ptr(),
            color.as_mut_ptr(),
        );
        if light_set != 0 || color_set != 0 {
            let mut r = (color[0] * 255.0) as c_int;
            if r > 255 {
                r = 255;
            }
            let mut g = (color[1] * 255.0) as c_int;
            if g > 255 {
                g = 255;
            }
            let mut b = (color[2] * 255.0) as c_int;
            if b > 255 {
                b = 255;
            }
            let mut i = (light / 4.0) as c_int;
            if i > 255 {
                i = 255;
            }
            (*ent).s.constantLight = r | (g << 8) | (b << 16) | (i << 24);
        }

        if (*ent).spawnflags & 128 != 0 {
            // can be used by the player's BUTTON_USE
            (*ent).r.svFlags |= SVF_PLAYER_USABLE;
        }

        (*ent).s.eType = entityType_t::ET_MOVER as c_int;
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));

        (*ent).s.pos.trType = trType_t::TR_STATIONARY;
        (*ent).s.pos.trBase = (*ent).pos1;
    }
}

