/// Raven `GlassUse`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2930-2948`
pub fn GlassUse(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        // no direct object to blame for the break, so fill the values with
        // whatever
        let mut temp1 = [
            ((*self_).r.mins[0] + (*self_).r.maxs[0]) * 0.5,
            ((*self_).r.mins[1] + (*self_).r.maxs[1]) * 0.5,
            ((*self_).r.mins[2] + (*self_).r.maxs[2]) * 0.5,
        ];

        let temp2 = [
            ((*other).r.mins[0] + (*other).r.maxs[0]) * 0.5,
            ((*other).r.mins[1] + (*other).r.maxs[1]) * 0.5,
            ((*other).r.mins[2] + (*other).r.maxs[2]) * 0.5,
        ];

        (*self_).pos2 = [
            temp1[0] - temp2[0],
            temp1[1] - temp2[1],
            temp1[2] - temp2[2],
        ];
        (*self_).pos1 = temp1;

        // Raven uses VectorNormalize, whose sqrt is the double libm call and which leaves
        // the vector untouched at zero length (so the scale yields (0,0,0)); an inline f32
        // sqrt double-rounds and turns the coincident-center case into NaN.
        VectorNormalize(&mut (*self_).pos2);
        (*self_).pos2 = [
            (*self_).pos2[0] * 390.0,
            (*self_).pos2[1] * 390.0,
            (*self_).pos2[2] * 390.0,
        ];

        GlassDie(
            ctx,
            self_,
            other,
            activator,
            100,
            meansOfDeath_t::MOD_UNKNOWN as c_int,
        );
    }
}

/// Raven `SP_func_glass`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2957-2990`
pub fn SP_func_glass(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        trap::SetBrushModel(
            ctx.engine,
            GSetBrushModelArgs::new(ent, std::ffi::CStr::from_ptr((*ent).model).to_owned()),
        );
        InitMover(ctx, ent);

        (*ent).r.svFlags = SVF_GLASS_BRUSH;

        (*ent).s.pos.trBase = (*ent).s.origin;
        (*ent).r.currentOrigin = (*ent).s.origin;
        if (*ent).health == 0 {
            (*ent).health = 1;
        }

        G_SpawnInt(
            ctx,
            c"maxshards".as_ptr(),
            c"0".as_ptr(),
            &mut (*ent).genericValue3 as *mut c_int,
        );

        (*ent).genericValue1 = 0;
        (*ent).genericValue4 = 1;
        (*ent).moverState = MOVER_POS1;

        if (*ent).spawnflags & 1 != 0 {
            (*ent).takedamage = qfalse;
        } else {
            (*ent).takedamage = qtrue;
        }

        (*ent).die = Some(EntDie::GlassDie).into();
        (*ent).use_ = Some(EntUse::GlassUse).into();
        (*ent).pain = Some(EntPain::GlassPain).into();
    }
}

/// Raven `func_wait_return_solid`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2995-3025`
pub fn func_wait_return_solid(ctx: GameContext<'_>, self_: *mut gentity_t) {
    unsafe {
        // once a frame, see if it's clear
        (*self_).clipmask = CONTENTS_BODY;
        if (*self_).spawnflags & 16 == 0 || G_TestEntityPosition(ctx, self_).is_null() {
            trap::SetBrushModel(
                ctx.engine,
                GSetBrushModelArgs::new(self_, std::ffi::CStr::from_ptr((*self_).model).to_owned()),
            );
            InitMover(ctx, self_);
            (*self_).s.pos.trBase = (*self_).s.origin;
            (*self_).r.currentOrigin = (*self_).s.origin;
            (*self_).r.svFlags &= !SVF_NOCLIENT;
            (*self_).s.eFlags &= !EF_NODRAW;
            (*self_).use_ = Some(EntUse::func_usable_use).into();
            (*self_).clipmask = 0;
            if !(*self_).target2.is_null() && *(*self_).target2 != 0 {
                G_UseTargets2(
                    ctx,
                    self_,
                    crate::ent_id::resolve(
                        (*ctx.world).g_entities.as_mut_ptr(),
                        (*self_).activator,
                    ),
                    (*self_).target2,
                );
            }
        } else {
            (*self_).clipmask = 0;
            (*self_).think = Some(EntThink::func_wait_return_solid).into();
            (*self_).nextthink = (*ctx.world).level.time + FRAMETIME;
        }
    }
}

/// Raven `func_usable_think`.
